import { normalizeReportMarkdown } from "./sre-incident-brief-report";

describe("normalizeReportMarkdown", () => {
  it("titles a brief that starts at its first section and adds the footer once", () => {
    expect(normalizeReportMarkdown("## Summary\nThe job failed.", "Incident #3: Checkout (evidence brief)")).toBe(
      "# Incident #3: Checkout (evidence brief)\n\n## Summary\nThe job failed.\n\n---\n**Generated by Supercheck AI.**",
    );
  });

  it("keeps an existing title and footer", () => {
    const legacy = "# Incident Investigation Report\n\nBody\n\n---\n**Generated by Supercheck AI.**";
    expect(normalizeReportMarkdown(legacy, "ignored")).toBe(legacy);
  });
});
